"""Regenerate docs/CHECKS.md from the built-in registry: python3 docs/gen_checks.py"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from fleetguard import checks as C  # noqa: E402


def render():
    lines = ["# Built-in checks", "",
             "Generated by `docs/gen_checks.py`. The *Topic* column names the CIS Benchmark topic a rule is modelled on;",
             "it is not a certified CIS-CAT result and does not quote benchmark numbering.", "",
             "| ID | Severity | Topic | Rule | Auto-fix |", "|---|---|---|---|---|"]
    for c in C.builtin_registry().all():
        fix = "no"
        if c.fix:
            fix = "yes (needs --allow-risky)" if c.fix.risky else "yes"
        lines.append("| %s | %s | %s | %s | %s |" % (c.id, c.severity, c.cis, c.title, fix))
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "CHECKS.md")
    with open(out, "w") as fh:
        fh.write(render())
    print("wrote", out)
